const input = $json.body ?? $json;
const required = ['token', 'event', 'gForce', 'bpm', 'o2'];
const missing = required.filter((k) => input[k] === undefined || input[k] === null || input[k] === '');
const g = Number(input.gForce);
const bpm = Number(input.bpm);
const o2 = Number(input.o2);
const errors = [];
if (missing.length) errors.push(`Missing fields: ${missing.join(', ')}`);
if (Number.isNaN(g)) errors.push('gForce must be numeric');
if (Number.isNaN(bpm)) errors.push('bpm must be numeric');
if (Number.isNaN(o2)) errors.push('o2 must be numeric');
if (input.token && input.token !== 'AEGIS_AUTH_774') errors.push('Invalid hardware token');
const isValid = errors.length === 0;
return [{
  json: {
    isValid,
    errors,
    receivedAt: new Date().toISOString(),
    incidentSeed: Date.now(),
    patientId: input.patientId || 'KIN-2024-0047',
    location: input.location || '12.824589,80.046896',
    event: String(input.event || 'UNKNOWN'),
    gForce: Number.isNaN(g) ? null : g,
    bpm: Number.isNaN(bpm) ? null : bpm,
    o2: Number.isNaN(o2) ? null : o2,
    ack: input.ack || {},
    metadata: { source: 'iot_webhook', workflow: 'closed_loop_v1' }
  }
}];

return [{
  json: {
    status: 'invalid_request',
    statusCode: 400,
    incidentId: null,
    message: 'Payload validation failed',
    errors: $json.errors || ['Unknown validation error'],
    requiredSchema: {
      token: 'string',
      event: 'string',
      gForce: 'number',
      bpm: 'number',
      o2: 'number',
      location: 'string (optional)',
      patientId: 'string (optional)',
      ack: 'object (optional)'
    },
    timestamp: new Date().toISOString()
  }
}];

const FALL_THRESHOLD = 15;
const g = $json.gForce;
const bpm = $json.bpm;
const o2 = $json.o2;
const event = ($json.event || '').toUpperCase();
const keywordFall = ['FALL', 'IMPACT', 'EMERGENCY'].some((k) => event.includes(k));
const isFall = keywordFall || g >= FALL_THRESHOLD;
let severity = 'LOW';
let riskScore = 0.20;
if (isFall) {
  severity = 'CRITICAL';
  riskScore = 0.95;
} else if ((bpm > 100 || o2 < 90) && bpm > 0 && o2 > 0) {
  severity = 'HIGH';
  riskScore = 0.82;
} else if (g >= 3) {
  severity = 'MEDIUM';
  riskScore = 0.55;
}
const incidentId = `INC-${$json.patientId}-${$json.incidentSeed}`;
const playbook = {
  CRITICAL: { actions: ['dispatch_ambulance', 'notify_neighbor', 'notify_doctor'], slaSeconds: 90, expectedProof: ['ambulance_ack', 'neighbor_ack'] },
  HIGH: { actions: ['notify_doctor', 'notify_neighbor'], slaSeconds: 120, expectedProof: ['doctor_ack'] },
  MEDIUM: { actions: ['notify_neighbor'], slaSeconds: 300, expectedProof: ['neighbor_ack'] },
  LOW: { actions: ['log_only'], slaSeconds: 0, expectedProof: [] }
};
return [{
  json: {
    ...$json,
    incidentId,
    isFall,
    severity,
    riskScore,
    state: 'triaged',
    playbook: playbook[severity],
    triageReasoning: isFall
      ? 'Fall detected by impact threshold or event keyword'
      : (severity === 'HIGH'
          ? 'Vitals out of safe range'
          : severity === 'MEDIUM'
            ? 'Instability detected; preventive intervention required'
            : 'No immediate risk, observation mode')
  }
}];

const now = new Date();
const actions = $json.playbook.actions || [];
const interventions = actions.map((action, idx) => ({
  interventionId: `${$json.incidentId}-A${idx + 1}`,
  action,
  channel: action.includes('notify') ? 'sms_email' : (action === 'dispatch_ambulance' ? 'dispatch_api' : 'internal'),
  dispatchedAt: now.toISOString(),
  status: action === 'log_only' ? 'completed' : 'dispatched'
}));
return [{
  json: {
    ...$json,
    state: 'action_dispatched',
    interventions,
    firstActionAt: now.toISOString(),
    verificationDeadline: new Date(now.getTime() + ($json.playbook.slaSeconds || 0) * 1000).toISOString()
  }
}];

const expectedProof = $json.playbook.expectedProof || [];
const ack = $json.ack || {};
const receivedProof = {
  ambulance_ack: !!ack.ambulance,
  neighbor_ack: !!ack.neighbor,
  doctor_ack: !!ack.doctor,
  patient_ack: !!ack.patient
};
const missingProof = expectedProof.filter((k) => !receivedProof[k]);
let state = 'verified_resolved';
let escalated = false;
let nextAction = 'close_incident';
if (missingProof.length > 0) {
  state = $json.severity === 'CRITICAL' ? 'escalated' : 'verification_pending';
  escalated = $json.severity === 'CRITICAL';
  nextAction = escalated ? 'escalate_to_backup_chain' : 'await_ack_or_retry';
}
const t0 = new Date($json.receivedAt).getTime();
const t1 = new Date($json.firstActionAt).getTime();
const timeToFirstActionSeconds = Math.max(0, Math.round((t1 - t0) / 1000));
return [{
  json: {
    status: 'ok',
    statusCode: 200,
    incidentId: $json.incidentId,
    patientId: $json.patientId,
    severity: $json.severity,
    riskScore: $json.riskScore,
    state,
    isFall: $json.isFall,
    telemetry: {
      event: $json.event,
      gForce: $json.gForce,
      bpm: $json.bpm,
      o2: $json.o2,
      location: $json.location
    },
    triageReasoning: $json.triageReasoning,
    interventions: $json.interventions,
    verification: {
      expectedProof,
      receivedProof,
      missingProof,
      deadline: $json.verificationDeadline,
      escalated,
      nextAction
    },
    kpis: {
      timeToFirstActionSeconds,
      interventionCount: ($json.interventions || []).length
    },
    timestamp: new Date().toISOString()
  }
}];
